/* DO NOT EDIT
@todo This file is copied from GUI and should be pulled out into a shared library.
See https://github.com/LLK/scratch-paint/issues/13 */

$ui-pane-border: #D9D9D9;
$ui-pane-gray: #F9F9F9;
$ui-background-blue: #e8edf1;

$text-primary: #575e75;

$looks-secondary: #855CD6;
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-secondary */

$red-primary: #FF661A;
$red-tertiary: #E64D00;

$sound-primary: #CF63CF;
$sound-tertiary: #A63FA6;

$control-primary: #FFAB19;

$data-primary: #FF8C1A;

$form-border: #E9EEF2;
@import '../../css/colors.css';

$arrow-border-width: 14px;

.dropdown {
    border: 1px solid $form-border;
    border-radius: 5px;
    overflow: visible;
    min-width: 3.5rem;
    color: $looks-secondary;
    padding: .5rem;
}

.mod-open {
    background-color: $form-border;
}

.dropdown-icon {
    width: .5rem;
    height: .5rem;
    vertical-align: middle;
    padding-bottom: .2rem;
}

[dir="ltr"] .dropdown-icon {
    margin-left: .5rem;
}

[dir="rtl"] .dropdown-icon {
    margin-right: .5rem;
}

.mod-caret-up {
    transform: rotate(180deg);
    padding-bottom: 0;
    padding-top: .2rem;
}
